import pytest
from fastapi import FastAPI, Form, File, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/test_order")
async def test_order(form_val: str = Form(...), file_val: UploadFile = File(...)):
    return {"form_val": form_val, "file_val": file_val.filename}

@app.post("/test_reverse_order")
async def test_reverse_order(file_val: UploadFile = File(...), form_val: str = Form(...)):
    return {"form_val": form_val, "file_val": file_val.filename}

@app.post("/test_multiple_files")
async def test_multiple_files(form_val: str = Form(...), file1: UploadFile = File(...), file2: UploadFile = File(...)):
    return {"form_val": form_val, "file1": file1.filename, "file2": file2.filename}

client = TestClient(app)

def test_order_success():
    files = {"file_val": ("test.txt", b"content")}
    data = {"form_val": "hello"}
    response = client.post("/test_order", data=data, files=files)
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "file_val": "test.txt"}

def test_reverse_order_success():
    files = {"file_val": ("test.txt", b"content")}
    data = {"form_val": "hello"}
    response = client.post("/test_reverse_order", data=data, files=files)
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "file_val": "test.txt"}

def test_multiple_files_success():
    files = {
        "file1": ("test1.txt", b"content1"),
        "file2": ("test2.txt", b"content2"),
    }
    data = {"form_val": "hello"}
    response = client.post("/test_multiple_files", data=data, files=files)
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "file1": "test1.txt", "file2": "test2.txt"}
